#!/bin/bash
# SPDX-License-Identifier: GPL-2.0-or-later
# Run clang-format on the lines a change adds or edits, in the files 6boot
# owns (SPDX GPL-2.0-or-later). Inherited m1n1 files and untouched lines are
# not checked, so nothing has to be reformatted to pass.
#
#   .github/format-changed.sh <base> [clang-format]
set -euo pipefail
base=$1
cf=${2:-clang-format}
status=0
checked=0
while IFS= read -r f; do
    case $f in data/*) continue ;; esac # generated by tools/die/gen_die.py
    head -n 3 "$f" | grep -q 'SPDX-License-Identifier: GPL-2.0-or-later' || continue
    lines=()
    while read -r start count; do
        [ "$count" -gt 0 ] && lines+=("--lines=$start:$((start + count - 1))")
    done < <(git diff -U0 --no-color "$base" HEAD -- "$f" |
        sed -nE 's/^@@ -[0-9,]+ \+([0-9]+)(,([0-9]+))? @@.*/\1 \3/p' |
        awk '{ print $1, ($2 == "" ? 1 : $2) }')
    [ ${#lines[@]} -eq 0 ] && continue
    checked=$((checked + 1))
    "$cf" --dry-run --Werror "${lines[@]}" "$f" || status=1
done < <(git diff --name-only --diff-filter=AM "$base" HEAD -- '*.c' '*.h')
echo "format-changed: $checked file(s) checked against $base"
exit $status
